-- SEED: 200 parcels + buildings for Villeneuve-la-Garenne (92078)

ON CONFLICT (parcel_id) DO NOTHING;

ON CONFLICT (parcel_id) DO NOTHING;

ON CONFLICT (parcel_id) DO NOTHING;

ON CONFLICT (parcel_id) DO NOTHING;

ON CONFLICT (building_id) DO NOTHING;

ON CONFLICT (building_id) DO NOTHING;

ON CONFLICT (building_id) DO NOTHING;

-- STEP 1: Building stats
SELECT p.parcel_id,
  COALESCE(SUM(ST_Area(ST_Intersection(p.geom,b.geom))),0),
  COUNT(DISTINCT b.building_id) FILTER (WHERE ST_Intersects(p.geom,b.geom)),
  COALESCE(SUM(ST_Area(ST_Intersection(p.geom,b.geom))*COALESCE(b.levels_est,1)),0),
  CASE WHEN p.area_m2>0 THEN COALESCE(SUM(ST_Area(ST_Intersection(p.geom,b.geom))),0)/p.area_m2 ELSE 0 END,
  now()
FROM public.parcels p LEFT JOIN public.buildings b ON ST_Intersects(p.geom,b.geom)
WHERE p.insee_code='92078' GROUP BY p.parcel_id,p.area_m2
ON CONFLICT (parcel_id) DO UPDATE SET built_footprint_m2=EXCLUDED.built_footprint_m2,building_count=EXCLUDED.building_count,existing_gfa_est=EXCLUDED.existing_gfa_est,coverage_ratio=EXCLUDED.coverage_ratio,updated_at=now();

-- STEP 2: Market stats (use DVF if available, fallback 4200 EUR/m2 for VLG)
SELECT p.parcel_id,
  COALESCE(c.prix_m2_median,4200),
  CASE WHEN COALESCE(c.prix_m2_median,4200)>=6000 THEN 10 WHEN COALESCE(c.prix_m2_median,4200)>=4500 THEN 8 WHEN COALESCE(c.prix_m2_median,4200)>=3000 THEN 6 WHEN COALESCE(c.prix_m2_median,4200)>=2000 THEN 4 ELSE 2 END,
  EXTRACT(YEAR FROM now())::int, now()
FROM public.parcels p
LEFT JOIN LATERAL (SELECT prix_m2_median FROM public.dvf_clusters_commune WHERE cluster_id LIKE p.insee_code||'_%' ORDER BY count DESC LIMIT 1) c ON true
WHERE p.insee_code='92078'
ON CONFLICT (parcel_id) DO UPDATE SET median_price_m2=EXCLUDED.median_price_m2,market_tension_score=EXCLUDED.market_tension_score,updated_at=now();

-- STEP 3: Constructibility (Zone U defaults)
SELECT p.parcel_id,'U',12,0.40,0.20,0.85,0.90,
  LEAST(p.area_m2*0.40,p.area_m2*0.80*0.85),
  GREATEST(1,FLOOR(12/3.5))::int,
  LEAST(p.area_m2*0.40,p.area_m2*0.80*0.85)*GREATEST(1,FLOOR(12/3.5))*0.90,
  GREATEST(0,LEAST(p.area_m2*0.40,p.area_m2*0.80*0.85)*GREATEST(1,FLOOR(12/3.5))*0.90-COALESCE(bs.existing_gfa_est,0)),
  CASE WHEN (LEAST(p.area_m2*0.40,p.area_m2*0.80*0.85)*GREATEST(1,FLOOR(12/3.5))*0.90)>0
    THEN GREATEST(0,1-COALESCE(bs.existing_gfa_est,0)/(LEAST(p.area_m2*0.40,p.area_m2*0.80*0.85)*GREATEST(1,FLOOR(12/3.5))*0.90)) ELSE 0 END,
  now()
FROM public.parcels p LEFT JOIN public.parcel_building_stats bs ON bs.parcel_id=p.parcel_id
WHERE p.insee_code='92078'
ON CONFLICT (parcel_id) DO UPDATE SET dominant_zone_family=EXCLUDED.dominant_zone_family,buildable_footprint_est=EXCLUDED.buildable_footprint_est,floors_est=EXCLUDED.floors_est,estimated_gfa=EXCLUDED.estimated_gfa,residual_potential_est=EXCLUDED.residual_potential_est,underuse_ratio=EXCLUDED.underuse_ratio,updated_at=now();

-- STEP 4: Final scores
SELECT p.parcel_id,
  ROUND((0.30*sub.underuse_score+0.25*sub.zoning_score+0.20*sub.market_score+0.15*sub.size_score+0.10*sub.land_value_score),2),
  sub.underuse_score,sub.zoning_score,sub.market_score,sub.size_score,sub.land_value_score,
  CASE WHEN pc.dominant_zone_family IN('U','AU') AND p.area_m2>=600 AND pc.underuse_ratio>=0.70 THEN 'densification_residentielle'
    WHEN pc.dominant_zone_family='U' AND p.area_m2 BETWEEN 300 AND 700 AND pc.underuse_ratio>=0.60 THEN 'division_parcellaire'
    WHEN pc.dominant_zone_family='U' AND COALESCE(bs.coverage_ratio,0)<0.15 THEN 'dent_creuse'
    ELSE 'analyse_complementaire' END,
  calc.lv, calc.pv,
  jsonb_build_object('area_m2',p.area_m2,'underuse_ratio',pc.underuse_ratio,'dominant_zone_family',pc.dominant_zone_family,'median_price_m2',pms.median_price_m2,'estimated_gfa',pc.estimated_gfa,'residual_potential_est',pc.residual_potential_est,'coverage_ratio',bs.coverage_ratio),
  now()
FROM public.parcels p
JOIN public.parcel_constructibility pc ON pc.parcel_id=p.parcel_id
LEFT JOIN public.parcel_market_stats pms ON pms.parcel_id=p.parcel_id
LEFT JOIN public.parcel_building_stats bs ON bs.parcel_id=p.parcel_id
CROSS JOIN LATERAL (SELECT (pc.estimated_gfa*0.75*COALESCE(pms.median_price_m2,0)) AS pv,
  (pc.estimated_gfa*0.75*COALESCE(pms.median_price_m2,0))-(pc.estimated_gfa*1300)-(pc.estimated_gfa*100)-((pc.estimated_gfa*0.75*COALESCE(pms.median_price_m2,0))*0.03)-((pc.estimated_gfa*0.75*COALESCE(pms.median_price_m2,0))*0.08) AS lv) calc
CROSS JOIN LATERAL (SELECT
  CASE WHEN pc.underuse_ratio>=0.80 THEN 10 WHEN pc.underuse_ratio>=0.60 THEN 8 WHEN pc.underuse_ratio>=0.40 THEN 6 WHEN pc.underuse_ratio>=0.20 THEN 4 ELSE 1 END AS underuse_score,
  CASE WHEN pc.dominant_zone_family='U' THEN 9 WHEN pc.dominant_zone_family='AU' THEN 7 WHEN pc.dominant_zone_family='A' THEN 2 WHEN pc.dominant_zone_family='N' THEN 1 ELSE 3 END AS zoning_score,
  CASE WHEN pms.median_price_m2>=6000 THEN 10 WHEN pms.median_price_m2>=4500 THEN 8 WHEN pms.median_price_m2>=3000 THEN 6 WHEN pms.median_price_m2>=2000 THEN 4 ELSE 2 END AS market_score,
  CASE WHEN p.area_m2>=1000 THEN 9 WHEN p.area_m2>=600 THEN 7 WHEN p.area_m2>=300 THEN 5 ELSE 2 END AS size_score,
  CASE WHEN calc.lv>=1500000 THEN 10 WHEN calc.lv>=800000 THEN 8 WHEN calc.lv>=400000 THEN 6 WHEN calc.lv>=150000 THEN 4 ELSE 2 END AS land_value_score
) sub
WHERE p.insee_code='92078'
ON CONFLICT (parcel_id) DO UPDATE SET mutability_score=EXCLUDED.mutability_score,underuse_score=EXCLUDED.underuse_score,zoning_score=EXCLUDED.zoning_score,market_score=EXCLUDED.market_score,size_score=EXCLUDED.size_score,land_value_score=EXCLUDED.land_value_score,best_use=EXCLUDED.best_use,land_value_est=EXCLUDED.land_value_est,program_value_est=EXCLUDED.program_value_est,explanation_json=EXCLUDED.explanation_json,computed_at=now();
